  logScale = false,
  lockVisibleRange = false,
  invertScale = false,
  isLineChart = false,
): ScaleY {
  let min = Infinity;
  let max = -Infinity;
  let hasValue = false;

  const start = Math.max(Math.floor(startIdx), 0);
  const end = Math.min(Math.ceil(endIdx), bars.length - 1);

  for (let i = start; i <= end; i++) {
    const bar = bars[i];
    if (isLineChart) {
      const val = bar.close;
      if (val < min) min = val;
      if (val > max) max = val;
    } else {
      if (bar.low < min) min = bar.low;
      if (bar.high > max) max = bar.high;
    }
    hasValue = true;
